'use strict';

const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const fs = require('node:fs');
const net = require('node:net');
const os = require('node:os');
const path = require('node:path');
const { once } = require('node:events');
const test = require('node:test');

const projectRoot = path.join(__dirname, '..');

async function availablePort() {
  const socket = net.createServer();
  socket.listen(0, '127.0.0.1');
  await once(socket, 'listening');
  const { port } = socket.address();
  await new Promise((resolve, reject) => socket.close(error => error ? reject(error) : resolve()));
  return port;
}

async function waitForServer(child, origin, getOutput) {
  const deadline = Date.now() + 10000;
  while (Date.now() < deadline) {
    if (child.exitCode !== null) throw new Error(`Server exited before ready:\n${getOutput()}`);
    try {
      const response = await fetch(`${origin}/api/posts`);
      if (response.ok) return;
    } catch {}
    await new Promise(resolve => setTimeout(resolve, 100));
  }
  throw new Error(`Server did not become ready:\n${getOutput()}`);
}

test('supports Unicode password limits and maximum-size post content', async t => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'minimalist-blog-test-'));
  const port = await availablePort();
  const origin = `http://127.0.0.1:${port}`;
  const child = spawn(process.execPath, [path.join(projectRoot, 'server.js')], {
    cwd: projectRoot,
    env: {
      ...process.env,
      PORT: String(port),
      APP_ORIGIN: origin,
      BLOG_DB_PATH: path.join(tempDir, 'blog.sqlite')
    },
    stdio: ['ignore', 'pipe', 'pipe']
  });
  let output = '';
  child.stdout.setEncoding('utf8').on('data', chunk => { output += chunk; });
  child.stderr.setEncoding('utf8').on('data', chunk => { output += chunk; });

  t.after(async () => {
    if (child.exitCode === null) {
      child.kill('SIGTERM');
      await Promise.race([
        once(child, 'exit'),
        new Promise(resolve => setTimeout(resolve, 5000))
      ]);
      if (child.exitCode === null) child.kill();
    }
    fs.rmSync(tempDir, { recursive: true, force: true });
  });

  await waitForServer(child, origin, () => output);
  const headers = {
    'Content-Type': 'application/json',
    Origin: origin,
    'X-Requested-With': 'XMLHttpRequest'
  };
  const register = (username, email, password) => fetch(`${origin}/api/auth/register`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ username, email, password })
  });

  const tooShort = await register('shortpass', 'short@example.com', '😀'.repeat(6));
  assert.equal(tooShort.status, 400);

  const created = await register('unicodeuser', 'unicode@example.com', '😀'.repeat(12));
  assert.equal(created.status, 201);

  const login = await fetch(`${origin}/api/auth/login`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ identity: 'unicodeuser', password: '😀'.repeat(12) })
  });
  assert.equal(login.status, 200);
  const cookie = login.headers.get('set-cookie').split(';')[0];

  const content = '漢'.repeat(10000);
  const post = await fetch(`${origin}/api/posts`, {
    method: 'POST',
    headers: { ...headers, Cookie: cookie },
    body: JSON.stringify({ title: 'Maximum length story', content })
  });
  assert.equal(post.status, 201);
  assert.equal((await post.json()).post.content.length, 10000);

  const oversized = await fetch(`${origin}/api/auth/register`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ username: 'largebody', email: 'large@example.com', password: 'x'.repeat(140000) })
  });
  assert.equal(oversized.status, 413);
  assert.equal((await oversized.json()).error, 'Request body is too large.');
});
